                  : require("assets/icons/guest-polygon.png")
              }
              width={7}
              height={6}
              style={styles.polygon}
            />
          </Block>
        )}
      </Block>
      <SeenBy userIds={seenByUserIds} messageWidth={200} />
    </Block>
  );
};

