  polygon: {
    width: 7,
    height: 6,
  },
  trash: {
    width: 20,
    height: 20,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type FileMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { getEventId, getEventTextContent } from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { TimelineService } from "modules/timeline/service/TimelineService";
import type { FC } from "react";
import { useState } from "react";
import { Dimensions, Image, Share } from "react-native";
import {
  Button,
  Loading,
  MessageTimestamp,
  PinIndicator,
  SeenBy,
} from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { copyToStablePath, formatBytes, isPdf, offlineToastHelper } from "shared/utils";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageSender } from "../message-sender";

interface Props {
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const getFileContent = (
  event: EventTimelineItem,
): FileMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.File) return msgType.inner.content;
    }
  }
  return null;
};

const { width } = Dimensions.get("window");

export const FileMessage: FC<Props> = ({
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const content = getFileContent(event);
  const eventId = getEventId(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const [isDownloading, setIsDownloading] = useState(false);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const maxWidth = width - 60;
  const seenByUserIds = TimelineService.getReadReceiptUserIds(event);

  const handleOpen = async () => {
    if (!content?.source || !MatrixCore.instance) return;

    try {
      setIsDownloading(true);

      const ext =
        content.info?.mimetype?.split("/")[1] ??
        content.filename?.split(".").pop() ??
        "bin";
      const filename = content.filename ?? `file-${eventId}.${ext}`;

      const mediaHandle = await MatrixCore.instance.getMediaFile(
        content.source,
        filename,
        content.info?.mimetype || "application/octet-stream",
        false,
        undefined,
      );

      const filePath = mediaHandle.path();

      if (isPdf(content)) {
        const stableUrl = await copyToStablePath(filePath, filename);
        NavigationContainerRef.navigate("pdfViewer", {
          fileUrl: stableUrl,
          filename,
        });
        return;
      }

      const fileUrl = filePath.startsWith("file://")
        ? filePath
        : `file://${filePath}`;
      await Share.share({ url: fileUrl });
    } catch {
      offlineToastHelper("Failed to open file");
    } finally {
      setIsDownloading(false);
    }
  };

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        isUser={isUser}
        senderId={senderId}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />
      <MessageLongPressWrapper
        event={event}
        content={getEventTextContent(event)}
      >
        <Block flexDirection={isUser ? "row-reverse" : "row"}>
          <Block
            paddings={12}
            background={isUser ? Colors.primary : Colors.message}
            border={{ borderRadius: 16 }}
            flexDirection={isUser ? "row-reverse" : "row"}
            gap={12}
            align="center"
            maxWidth={maxWidth}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            <Button.Wrapper disabled={isDownloading} onPress={handleOpen}>
              <Block
                width={40}
                height={40}
                align="center"
                justify="center"
                background={Colors.white20}
                border={{ borderRadius: 20 }}
              >
                {isDownloading ? (
                  <Loading isFullScreen={false} />
                ) : (
                  <Image
                    source={require("assets/icons/download.png")}
                    style={{ width: 20, height: 20 }}
                    tintColor={Colors.white}
                  />
                )}
              </Block>
            </Button.Wrapper>
            <Block gap={2} flex={{ flexShrink: 1 }} minWidth={0}>
              <Text size={TextSize.small} color="white" numberOfLines={1}>
                {content.filename ?? "File"}
              </Text>
              {content.info?.size != null && (
                <Text
                  size={TextSize.tiny}
                  color={Colors.white50}
                  numberOfLines={1}
                >
                  {formatBytes(content.info.size)}
                </Text>
              )}
            </Block>
            <MessageTimestamp event={event} isUser={isUser} />
          </Block>
          <PinIndicator event={event} />
        </Block>
      </MessageLongPressWrapper>
      <SeenBy userIds={seenByUserIds} messageWidth={messageWidth} />
    </Block>
  );
};

import { Block, Text } from "@prototyp/skeletor";
import {
  EmbeddedEventDetails_Tags,
  type EventTimelineItem,
  type MediaSourceInterface,
  MessageType_Tags,
  MsgLikeKind_Tags,
  ProfileDetails_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import {
  cleanMentions,
  getEventTextContent,
  getMessageTextContent,
} from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import { Dimensions, Image, StyleSheet } from "react-native";
import { MessageTimestamp, PinIndicator, SeenBy } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { MentionText } from "../mention-text";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageReactionsOverlay } from "../message-reactions-overlay";
import { MessageSender } from "../message-sender";
import { ReplyPayload } from "../reply-paylaod";

interface Props {
  roomId: string;
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const { width } = Dimensions.get("window");

// Parse <a href="https://matrix.to/#/@user:server">@DisplayName</a> tags from
// formatted_body HTML into a lowercase-displayName → userId map.
// This is the sync fast path — no profile loading needed.
const parseMentionMapFromHtml = (html: string): Map<string, string> => {
  const regex =
    /<a[^>]+href="https:\/\/matrix\.to\/#\/(@[^"]+)"[^>]*>@?([^<]+)<\/a>/gi;
  const matches = Array.from(html.matchAll(regex));
  return new Map(matches.map((m) => [m[2].toLowerCase(), m[1]]));
};

export const TextMessage: FC<Props> = ({
  roomId,
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const [messageWidth, setMessageWidth] = useState(116);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const seenByUserIds = TimelineService.getReadReceiptUserIds(event);
  const [mentionMap, setMentionMap] = useState<Map<string, string>>(new Map());
  // Some clients (Element X) put raw markdown links in the body:
  // [@Name](matrix.to/#/@user:server)  — link text has @
  // [Name](matrix.to/#/@user:server)   — link text without @
  // Detect by the /#/@ pattern in the URL (user permalink) and normalize to @Name.
  const content = cleanMentions(getEventTextContent(event));
  const maxWidth = width - 60;
  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);

  const { formattedBody, mentionUserIds, isEdited } = useMemo(() => {
    if (event.content.tag !== TimelineItemContent_Tags.MsgLike)
      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
    const kind = event.content.inner.content.kind;
    if (kind?.tag !== MsgLikeKind_Tags.Message) {
      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
    }
    const msgType = kind.inner.content.msgType;
    const html =
      msgType?.tag === MessageType_Tags.Text
        ? msgType.inner.content.formatted?.body
        : undefined;
    return {
      formattedBody: html,
      mentionUserIds: kind.inner.content.mentions?.userIds ?? [],
      isEdited: kind.inner.content.isEdited,
    };
  }, [event]);

  useEffect(() => {
    // Fast path: extract mention map directly from formatted_body HTML
    if (formattedBody) {
      const map = parseMentionMapFromHtml(formattedBody);
      if (map.size > 0) {
        setMentionMap(map);
        return;
      }
    }

    // Fallback: load profiles for mentioned user IDs (messages without formatted_body)
    if (!mentionUserIds.length) return;
    const client = MatrixCore.getClient();
    Promise.allSettled(mentionUserIds.map((id) => client.getProfile(id))).then(
      (results) => {
        const map = new Map<string, string>();
        results.forEach((result, i) => {
          const userId = mentionUserIds[i];
          const displayName =
            result.status === "fulfilled"
              ? (result.value.displayName ?? userId)
              : userId;
          map.set(displayName.toLowerCase(), userId);
        });
        setMentionMap(map);
      },
    );
  }, [formattedBody, mentionUserIds]);

  const replyPayload = useMemo(() => {
    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;

    const inReplyTo = event.content.inner.content.inReplyTo;

    if (!inReplyTo) return null;

    const eventDetails = inReplyTo.event();
    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;

    const senderName =
      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
        ? (eventDetails.inner.senderProfile.inner.displayName ??
          eventDetails.inner.sender)
        : eventDetails.inner.sender;

    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
      null;
    const replyContent = eventDetails.inner.content;

    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
      const kind = replyContent.inner.content.kind;
      if (kind?.tag === MsgLikeKind_Tags.Message) {
        const msgType = kind.inner.content.msgType;
        if (msgType?.tag === MessageType_Tags.Image) {
          mediaSource = {
            source: msgType.inner.content.source,
            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
          };
        }
        if (msgType?.tag === MessageType_Tags.Video) {
          mediaSource = {
            source: msgType.inner.content.source,
            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
          };
        }
      }
    }

    return {
      eventId: inReplyTo.eventId(),
      senderName,
      content: getMessageTextContent(eventDetails.inner.content),
      mediaSource,
    };
  }, [event]);

  const handleReplyPress = useCallback(() => {
    if (replyPayload) setScrollToEventId(replyPayload.eventId);
  }, [replyPayload, setScrollToEventId]);

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />
      <MessageLongPressWrapper event={event} content={content}>
        <Block flexDirection={isUser ? "row-reverse" : "row"}>
          <Block
            paddings={12}
            background={isUser ? Colors.primary : Colors.message}
            border={{ borderRadius: 24 }}
            align="stretch"
            gap={12}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            maxWidth={maxWidth}
          >
            <ReplyPayload
              replyPayload={replyPayload}
              onPress={handleReplyPress}
            />
            <Block
              flexDirection={isUser ? "row-reverse" : "row"}
              align="flex-end"
              justify="space-between"
              flex={{ flexWrap: "wrap" }}
              gap={{ row: 4, col: 16 }}
            >
              {mentionMap.size > 0 ? (
                <MentionText
                  isUser={isUser}
                  body={content}
                  mentionMap={mentionMap}
                  onMentionPress={onMemberPress}
                />
              ) : (
                <Text size={TextSize.small} color="white">
                  {content}
                </Text>
              )}
              <MessageTimestamp
                event={event}
                isUser={isUser}
                isEdited={isEdited}
              />
            </Block>
            {isPreviousSameSender && (
              <Block
                absolute
                offsets={
                  isUser
                    ? {
                        right: 6,
                        bottom: 2,
                      }
                    : {
                        left: 6,
                        bottom: 2,
                      }
                }
              >
                <Image
                  source={
                    isUser
                      ? require("assets/icons/polygon.png")
                      : require("assets/icons/guest-polygon.png")
                  }
                  width={7}
                  height={6}
                  style={styles.polygon}
                />
              </Block>
            )}
          </Block>
          <PinIndicator event={event} />
        </Block>
      </MessageLongPressWrapper>
      <MessageReactionsOverlay event={event} roomId={roomId} />
      <SeenBy userIds={seenByUserIds} messageWidth={messageWidth} />
    </Block>
  );
};

const styles = StyleSheet.create({
  polygon: {
    width: 7,
    height: 6,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
  type VideoMessageContent,
} from "@unomed/react-native-matrix-sdk";
import { useSetAtom } from "jotai";
import { MatrixBaseURL } from "modules/matrix-client/const";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { fetchMedia, getEventTextContent } from "modules/matrix-client/utils";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useEffect, useMemo, useState } from "react";
import { Image } from "react-native";
import Video from "react-native-video";
import {
  Loading,
  MessageTimestamp,
  PinIndicator,
  SeenBy,
} from "shared/components";
import { MAX_MEDIA_WIDTH } from "shared/const";
import { Colors, TextSize } from "shared/styles";
import { MessageLongPressWrapper } from "../message-long-press-wrapper";
import { MessageReactionsOverlay } from "../message-reactions-overlay";
import { MessageSender } from "../message-sender";

interface Props {
  roomId: string;
  event: EventTimelineItem;
  isPreviousSameSender: boolean;
  onMemberPress?: (member: MemberDetailsPayload) => void;
}

const getVideoContent = (
  event: EventTimelineItem,
): VideoMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Video) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

export const VideoMessage: FC<Props> = ({
  roomId,
  event,
  isPreviousSameSender,
  onMemberPress,
}) => {
  const content = getVideoContent(event);
  const [messageWidth, setMessageWidth] = useState(40);
  const originalWidth = Number(content?.info?.width) || 0;
  const originalHeight = Number(content?.info?.height) || 0;
  const scaleRatio = Math.min(MAX_MEDIA_WIDTH / originalWidth, 1);
  const targetWidth = Math.round(originalWidth * scaleRatio);
  const targetHeight = Math.round(originalHeight * scaleRatio);
  const [uri, setUri] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const isUser = event.isOwn;
  const sender = event.senderProfile;
  const senderId = event.sender;
  const caption = content?.caption;
  const background = useMemo(() => {
    if (!caption) return "transparent";
    return isUser ? Colors.primary : Colors.message;
  }, [caption, isUser]);
  const seenByUserIds = TimelineService.getReadReceiptUserIds(event);
  const setVideoViewerUri = useSetAtom(TimelineAtoms.videoViewerUri);

  const openVideoViewer = useCallback(() => {
    if (!uri || isLoading) return;
    setVideoViewerUri(uri);
  }, [uri, isLoading, setVideoViewerUri]);

  useEffect(() => {
    if (!content?.source.url()) return;

    fetchMedia({
      serverUrl: MatrixCore.instance?.session().homeserverUrl || MatrixBaseURL,
      mediaSource: content.source,
      mimeType: content.info?.mimetype || "video/mp4",
    })
      .then(setUri)
      .catch(console.error)
      .finally(() => setIsLoading(false));
  }, [content]);

  if (!content) return null;

  return (
    <Block
      align={isUser ? "flex-end" : "flex-start"}
      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
    >
      <MessageSender
        sender={sender}
        senderId={senderId}
        isUser={isUser}
        isPreviousSameSender={isPreviousSameSender}
        onMemberPress={onMemberPress}
      />

      <Block flexDirection={isUser ? "row-reverse" : "row"}>
        <Block
          background={background}
          border={{ borderRadius: 12 }}
          paddings={caption ? [4, 4, 12] : 0}
          gap={8}
        >
          <Block
            background="transparent"
            border={{
              borderRadius: 12,
            }}
            align="center"
            overflow="hidden"
            width={targetWidth}
            height={targetHeight}
            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
          >
            {isLoading ? (
              <Block
                width="100%"
                height="100%"
                background={Colors.white20}
                align="center"
                justify="center"
              >
                <Loading isFullScreen={false} />
              </Block>
            ) : uri ? (
              <>
                <MessageLongPressWrapper
                  event={event}
                  content={getEventTextContent(event)}
                  onFinalize={openVideoViewer}
                >
                  <Block
                    absolute
                    offsets={{ top: 0, left: 0, right: 0, bottom: 0 }}
                    zIndex={10}
                    border={{ borderRadius: 12 }}
                    align="center"
                    justify="center"
                    pointerEvents="none"
                  >
                    <Image source={require("assets/icons/play.png")} />
                  </Block>
                  <Video
                    source={{ uri }}
                    style={{
                      width: targetWidth,
                      height: targetHeight,
                    }}
                    resizeMode="contain"
                    paused
                    pointerEvents="none"
                  />
                </MessageLongPressWrapper>
              </>
            ) : null}
          </Block>

          {caption ? (
            <Block
              maxWidth={targetWidth}
              justify="space-between"
              flexDirection={isUser ? "row-reverse" : "row"}
              gap={{
                row: 4,
                col: 16,
              }}
              align="center"
              flex={{ flexWrap: "wrap" }}
              paddings={[0, 8]}
              onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
            >
              <Text size={TextSize.small} color="white">
                {caption}
              </Text>
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          ) : (
            <Block
              flexDirection={isUser ? "row" : "row-reverse"}
              gap={4}
              align="center"
              margins={{ marginLeft: isUser ? 0 : "auto" }}
            >
              <MessageTimestamp event={event} isUser={isUser} />
            </Block>
          )}
        </Block>
        <PinIndicator event={event} />
      </Block>
      <MessageReactionsOverlay event={event} roomId={roomId} />
      <SeenBy userIds={seenByUserIds} messageWidth={messageWidth} />
    </Block>
  );
};

